with with_windows as (select id, store_id, product_id, quantity, last_restock, row_number() over (order by last_restock desc, id asc) as seq_no, stddev_samp(quantity) over (partition by product_id) as product_id_stddev_samp_quantity, ntile(5) over (partition by store_id, product_id order by quantity desc, id asc) as quantity_bucket from inventory) select case when product_id_stddev_samp_quantity >= 261 then 'HIGH' else 'LOW' end as product_id_stddev_samp_quantity_tier, date_trunc('week', last_restock) as week_start, count(distinct id) as distinct_ids, percentile_approx(quantity, array(0.25, 0.5, 0.75)) as quantity_quartiles, percentile_approx(product_id_stddev_samp_quantity, array(0.25, 0.5, 0.75)) as product_id_stddev_samp_quantity_quartiles from with_windows group by case when product_id_stddev_samp_quantity >= 261 then 'HIGH' else 'LOW' end, date_trunc('week', last_restock) order by distinct_ids asc nulls first
